export default function HomeContent(){const[pokemon,setPokemon]=useState<Details[]>([]),[error,setError]=useState('');useEffect(()=>{let active=true;Promise.all([25,4,1,7].map(id=>api<Details>(`/pokemon/${id}`))).then(value=>{if(active)setPokemon(value);}).catch(e=>{if(active)setError(e.message);});return()=>{active=false;};},[]);return <>
<section className="pk-hero"><div className="pk-container pk-hero-grid"><div><p className="pk-eyebrow">♫ UMA NOVA AVENTURA ESPERA POR VOCÊ</p><h1>Sua jornada<br/>Pokémon<br/><em>começa aqui!</em></h1><p>Explore o mundo Pokémon, capture seus favoritos, monte equipes incríveis e torne-se um verdadeiro Mestre Pokémon.</p><div className="pk-actions"><Link className="pk-button" href="/pokedex">⌕ Explorar Pokédex</Link><Link className="pk-button secondary" href="/cadastro">Começar jornada →</Link></div><small>Uma jornada de descobertas e conquistas.</small></div><div className="pk-hero-circle">{pokemon[0]?.spriteUrl&&<img src={pokemon[0].spriteUrl} alt="Pikachu"/>}<span className="pk-hero-tag">ELÉTRICO <strong>Pikachu</strong><small>#025</small></span></div></div></section>
